"use client";
import { useState, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import { api } from "./api";
import { Button, Card, Field, inputClass, Notice } from "./ui";

type Hours = { weekday: number; open: string; close: string };
type Resource = { id?: string; name: string; capacity: number; type: string };
type Service = { id?: string; name: string; description: string; duration_min: number | null; price_cents: number | null; currency: string; resource_type: string };
type Faq = { question: string; answer: string };
type Props = {
  businessId: string;
  business: { name: string; type: string; timezone: string; description: string; address: string; phone: string; contact_email: string; has_logo: boolean; online_booking_enabled: boolean };
  policies: Record<string, number | string | boolean>;
  hours: Hours[]; closures: { id: string; label: string; reason: string }[];
  resources: Resource[]; services: Service[];
  agent: { name: string; tone: string; languages: string[]; greeting: string; extra_instructions: string; handoff_contact: string };
  faqs: Faq[];
  ai: { kind: string; label: string }; email: { delivers: boolean; name: string };
  whatsapp: { platformReady: boolean; connected: boolean; status: string; phoneNumberId: string; displayNumber: string; lastError: string; webhookUrl: string; publicUrl: boolean };
  phone: { platformReady: boolean; connected: boolean; number: string; sms: boolean; voice: boolean; transferTo: string; lastError: string; smsUrl: string; voiceUrl: string; publicUrl: boolean };
  team: { members: { id: string; name: string; email: string; role: string }[]; invitations: { id: string; email: string; role: string }[]; me: string } | null;
};

const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const RESOURCE_TYPES = [["table", "Table"], ["staff", "Staff member"], ["room", "Room"], ["equipment", "Equipment"], ["slot", "Slot"]];
const int = (v: string) => Math.max(0, Math.floor(Number(v) || 0));

/** One independently saved block of settings. */
function Section({ title, hint, children, onSave, saveLabel = "Save" }: { title: string; hint?: string; children: ReactNode; onSave?: () => Promise<unknown>; saveLabel?: string }) {
  const router = useRouter();
  const [state, setState] = useState<{ busy: boolean; ok: string; error: string }>({ busy: false, ok: "", error: "" });
  return (
    <Card className="p-5">
      <h2 className="text-xl font-bold">{title}</h2>
      {hint && <p className="mt-0.5 text-[15px] text-ink-soft">{hint}</p>}
      <div className="mt-4 space-y-4">{children}</div>
      {onSave && (
        <div className="mt-4 flex items-center gap-3">
          <Button disabled={state.busy} onClick={async () => {
            setState({ busy: true, ok: "", error: "" });
            try { await onSave(); setState({ busy: false, ok: "Saved", error: "" }); router.refresh(); }
            catch (e) { setState({ busy: false, ok: "", error: (e as Error).message }); }
          }}>{state.busy ? "Saving…" : saveLabel}</Button>
          {state.ok && <span role="status" className="font-semibold text-[#087a5d]">{state.ok}</span>}
          {state.error && <span role="alert" className="text-rose">{state.error}</span>}
        </div>
      )}
    </Card>
  );
}

export function SettingsPanel(p: Props) {
  const router = useRouter();
  const save = (body: Record<string, unknown>) => api(`/api/b/${p.businessId}/settings`, { method: "PATCH", body });

  const [online, setOnline] = useState(p.business.online_booking_enabled);
  const [profile, setProfile] = useState({ name: p.business.name, description: p.business.description, address: p.business.address, phone: p.business.phone, contact_email: p.business.contact_email, timezone: p.business.timezone });
  const [logoMsg, setLogoMsg] = useState("");
  const [hours, setHours] = useState<Hours[]>(p.hours);
  const [closure, setClosure] = useState({ from: "", to: "", reason: "" });
  const [closureMsg, setClosureMsg] = useState("");
  const [resources, setResources] = useState<Resource[]>(p.resources);
  const [services, setServices] = useState<Service[]>(p.services);
  const [pol, setPol] = useState(p.policies);
  const [agent, setAgent] = useState({ ...p.agent, languages: p.agent.languages.join(", ") });
  const [faqs, setFaqs] = useState<Faq[]>(p.faqs);
  const [wa, setWa] = useState({ phoneNumberId: p.whatsapp.phoneNumberId, displayNumber: p.whatsapp.displayNumber, accessToken: "" });
  const [ph, setPh] = useState({ number: p.phone.number, sms: p.phone.sms, voice: p.phone.voice, transferTo: p.phone.transferTo });
  const [invite, setInvite] = useState({ email: "", role: "staff", url: "", error: "" });

  const polNum = (key: string, label: string, hint?: string, max = 100000) => (
    <Field label={label} hint={hint}><input type="number" min={0} max={max} className={inputClass} value={Number(pol[key])} onChange={(e) => setPol({ ...pol, [key]: int(e.target.value) })} /></Field>
  );
  const polText = (key: string, label: string, hint?: string) => (
    <Field label={label} hint={hint}><textarea rows={2} maxLength={1000} className={`${inputClass} py-2`} value={String(pol[key])} onChange={(e) => setPol({ ...pol, [key]: e.target.value })} /></Field>
  );

  return (
    <div className="space-y-5">
      <Card className="flex flex-wrap items-center justify-between gap-3 p-5">
        <div>
          <h2 className="text-xl font-bold">Online reservations</h2>
          <p className="text-[15px] text-ink-soft">{online ? "Customers can book on your booking page." : "Customers cannot book online. Staff can still add reservations."}</p>
        </div>
        <Button variant={online ? "danger" : "mint"} onClick={async () => { await save({ online_booking_enabled: !online }); setOnline(!online); router.refresh(); }}>{online ? "Turn off online reservations" : "Turn on online reservations"}</Button>
      </Card>

      <Section title="Business profile" onSave={() => save({ profile })}>
        <Field label="Name"><input className={inputClass} value={profile.name} maxLength={80} onChange={(e) => setProfile({ ...profile, name: e.target.value })} /></Field>
        <Field label="Short description" hint="Shown at the top of your booking page."><textarea rows={2} maxLength={1000} className={`${inputClass} py-2`} value={profile.description} onChange={(e) => setProfile({ ...profile, description: e.target.value })} /></Field>
        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Address"><input className={inputClass} value={profile.address} maxLength={200} onChange={(e) => setProfile({ ...profile, address: e.target.value })} /></Field>
          <Field label="Phone"><input className={inputClass} value={profile.phone} maxLength={40} onChange={(e) => setProfile({ ...profile, phone: e.target.value })} /></Field>
          <Field label="Contact email"><input type="email" className={inputClass} value={profile.contact_email} maxLength={160} onChange={(e) => setProfile({ ...profile, contact_email: e.target.value })} /></Field>
          <Field label="Time zone" hint="Changing this does not move existing reservations."><input className={inputClass} value={profile.timezone} onChange={(e) => setProfile({ ...profile, timezone: e.target.value })} /></Field>
        </div>
        <Field label="Logo" hint="PNG, JPEG or WebP, up to 1 MB. Shown on the booking page and on tickets.">
          <input type="file" accept="image/png,image/jpeg,image/webp" className="block text-[15px]" onChange={async (e) => {
            const f = e.target.files?.[0];
            if (!f) return;
            setLogoMsg("Uploading…");
            const res = await fetch(`/api/b/${p.businessId}/logo`, { method: "POST", body: f });
            const j = await res.json().catch(() => ({}));
            setLogoMsg(res.ok ? "Logo updated." : j?.error?.message ?? "Upload failed.");
            if (res.ok) router.refresh();
          }} />
        </Field>
        {logoMsg && <p role="status" className="text-[15px] text-ink-soft">{logoMsg}</p>}
      </Section>

      <Section title="Opening hours" hint="Add two periods on one day for a lunch and dinner service." onSave={() => save({ hours })}>
        {DAYS.map((d, i) => {
          const rows = hours.map((h, idx) => ({ h, idx })).filter((x) => x.h.weekday === i + 1);
          return (
            <div key={d} className="flex flex-wrap items-center gap-2">
              <span className="w-28 font-semibold">{d}</span>
              {rows.length === 0 && <span className="text-muted">Closed</span>}
              {rows.map(({ h, idx }) => (
                <span key={idx} className="flex items-center gap-1.5">
                  <input aria-label={`${d} opens`} type="time" className={`${inputClass} w-[7.5rem]`} value={h.open} onChange={(e) => setHours(hours.map((x, j) => (j === idx ? { ...x, open: e.target.value } : x)))} />
                  <span className="text-muted">to</span>
                  <input aria-label={`${d} closes`} type="time" className={`${inputClass} w-[7.5rem]`} value={h.close === "24:00" ? "23:59" : h.close} onChange={(e) => setHours(hours.map((x, j) => (j === idx ? { ...x, close: e.target.value } : x)))} />
                  <button type="button" aria-label={`Remove ${d} period`} className="rounded-lg px-2 py-1 text-rose hover:bg-rose-soft" onClick={() => setHours(hours.filter((_, j) => j !== idx))}>Remove</button>
                </span>
              ))}
              <button type="button" className="rounded-lg px-2 py-1 font-semibold text-brand hover:bg-paper" onClick={() => setHours([...hours, { weekday: i + 1, open: rows.length ? "18:00" : "12:00", close: "22:00" }])}>Add period</button>
            </div>
          );
        })}
      </Section>

      <Section title="Closures and holidays" hint="Whole days when nobody can book.">
        {p.closures.length === 0 ? <p className="text-ink-soft">No closures planned.</p> : (
          <ul className="divide-y divide-line rounded-xl ring-1 ring-line">
            {p.closures.map((c) => (
              <li key={c.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                <span><strong>{c.label}</strong>{c.reason ? `, ${c.reason}` : ""}</span>
                <button type="button" className="font-semibold text-rose" onClick={async () => { await api(`/api/b/${p.businessId}/closures?id=${c.id}`, { method: "DELETE" }); router.refresh(); }}>Remove</button>
              </li>
            ))}
          </ul>
        )}
        <div className="grid items-end gap-3 sm:grid-cols-[1fr_1fr_1.4fr_auto]">
          <Field label="From"><input type="date" className={inputClass} value={closure.from} onChange={(e) => setClosure({ ...closure, from: e.target.value, to: closure.to || e.target.value })} /></Field>
          <Field label="To"><input type="date" className={inputClass} value={closure.to} onChange={(e) => setClosure({ ...closure, to: e.target.value })} /></Field>
          <Field label="Reason (shown to customers)"><input className={inputClass} maxLength={120} value={closure.reason} onChange={(e) => setClosure({ ...closure, reason: e.target.value })} /></Field>
          <Button variant="quiet" disabled={!closure.from || !closure.to} onClick={async () => {
            try {
              const r = await api<{ existingReservations: number }>(`/api/b/${p.businessId}/closures`, { body: closure });
              setClosureMsg(r.existingReservations ? `Added. ${r.existingReservations} existing reservation(s) fall inside this closure and were not cancelled — review them in Reservations.` : "Added.");
              setClosure({ from: "", to: "", reason: "" }); router.refresh();
            } catch (e) { setClosureMsg((e as Error).message); }
          }}>Add closure</Button>
        </div>
        {closureMsg && <Notice tone="info">{closureMsg}</Notice>}
      </Section>

      <Section title={p.business.type === "restaurant" ? "Tables" : "Resources"} hint="What a booking occupies. Each can hold one booking at a time. Removing one keeps its past reservations." onSave={() => save({ resources })}>
        {resources.map((r, i) => (
          <div key={r.id ?? `new-${i}`} className="grid items-end gap-2 sm:grid-cols-[1.4fr_0.7fr_1fr_auto]">
            <Field label="Name"><input className={inputClass} maxLength={60} value={r.name} onChange={(e) => setResources(resources.map((x, j) => (j === i ? { ...x, name: e.target.value } : x)))} /></Field>
            <Field label="Capacity"><input type="number" min={1} max={500} className={inputClass} value={r.capacity} onChange={(e) => setResources(resources.map((x, j) => (j === i ? { ...x, capacity: Math.max(1, int(e.target.value)) } : x)))} /></Field>
            <Field label="Type"><select className={inputClass} value={r.type} onChange={(e) => setResources(resources.map((x, j) => (j === i ? { ...x, type: e.target.value } : x)))}>{RESOURCE_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select></Field>
            <Button variant="quiet" onClick={() => setResources(resources.filter((_, j) => j !== i))}>Remove</Button>
          </div>
        ))}
        <Button variant="quiet" onClick={() => setResources([...resources, { name: `${p.business.type === "restaurant" ? "Table" : "Resource"} ${resources.length + 1}`, capacity: 2, type: resources[0]?.type ?? "table" }])}>Add {p.business.type === "restaurant" ? "a table" : "a resource"}</Button>
      </Section>

      <Section title="Services" hint="What customers book. Leave length empty to use the standard booking length." onSave={() => save({ services })}>
        {services.map((s, i) => (
          <div key={s.id ?? `new-${i}`} className="grid items-end gap-2 rounded-xl bg-paper p-3 sm:grid-cols-[1.5fr_0.7fr_0.7fr_0.6fr_1fr_auto]">
            <Field label="Name"><input className={inputClass} maxLength={80} value={s.name} onChange={(e) => setServices(services.map((x, j) => (j === i ? { ...x, name: e.target.value } : x)))} /></Field>
            <Field label="Length (min)"><input type="number" min={5} className={inputClass} value={s.duration_min ?? ""} onChange={(e) => setServices(services.map((x, j) => (j === i ? { ...x, duration_min: e.target.value ? int(e.target.value) : null } : x)))} /></Field>
            <Field label="Price"><input type="number" min={0} step="0.01" className={inputClass} value={s.price_cents != null ? s.price_cents / 100 : ""} onChange={(e) => setServices(services.map((x, j) => (j === i ? { ...x, price_cents: e.target.value ? Math.round(Number(e.target.value) * 100) : null } : x)))} /></Field>
            <Field label="Currency"><input className={inputClass} maxLength={8} value={s.currency} onChange={(e) => setServices(services.map((x, j) => (j === i ? { ...x, currency: e.target.value } : x)))} /></Field>
            <Field label="Uses"><select className={inputClass} value={s.resource_type} onChange={(e) => setServices(services.map((x, j) => (j === i ? { ...x, resource_type: e.target.value } : x)))}>{RESOURCE_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select></Field>
            {services.length > 1 && <Button variant="quiet" onClick={() => setServices(services.filter((_, j) => j !== i))}>Remove</Button>}
          </div>
        ))}
        <Button variant="quiet" onClick={() => setServices([...services, { name: "New service", description: "", duration_min: null, price_cents: null, currency: services[0]?.currency ?? "", resource_type: services[0]?.resource_type ?? "table" }])}>Add a service</Button>
      </Section>

      <Section title="Booking rules" onSave={() => save({ policies: pol })}>
        <div className="grid gap-4 sm:grid-cols-3">
          {polNum("default_duration_min", "Booking length (min)")}
          {polNum("slot_interval_min", "Times every (min)")}
          {polNum("buffer_min", "Gap between bookings (min)", "Time to reset before the next booking.")}
          {polNum("max_party_size", "Largest online booking")}
          {polNum("min_notice_min", "Minimum notice (min)", "How far ahead customers must book.")}
          {polNum("max_advance_days", "Book up to (days ahead)")}
          {polNum("cancel_cutoff_min", "Changes close (min before)", "Customers can change or cancel until then.")}
          {polNum("early_checkin_min", "Check-in opens (min before)")}
          {polNum("late_grace_min", "Hold late arrivals (min)")}
        </div>
        {polText("cancellation_policy", "Cancellation policy", "Shown to customers and used by the assistant.")}
        {polText("late_policy", "Late arrival policy")}
        {polText("arrival_instructions", "Arrival instructions", "Printed on the ticket, for example: ask for the host at the entrance.")}
      </Section>

      <Section title="Assistant" hint={p.ai.kind === "llm" ? `Connected model: ${p.ai.label}.` : "No AI model is connected, so the built-in basic assistant answers. It understands common English booking phrases only. Connect a model in the server configuration (see README)."}
        onSave={() => save({ agent: { ...agent, languages: agent.languages.split(",").map((s) => s.trim()).filter(Boolean) }, faqs: faqs.filter((f) => f.question.trim() && f.answer.trim()) })}>
        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Name"><input className={inputClass} maxLength={40} value={agent.name} onChange={(e) => setAgent({ ...agent, name: e.target.value })} /></Field>
          <Field label="Tone"><input className={inputClass} maxLength={120} value={agent.tone} onChange={(e) => setAgent({ ...agent, tone: e.target.value })} /></Field>
          <Field label="Languages" hint="Comma separated. The first is the default."><input className={inputClass} value={agent.languages} onChange={(e) => setAgent({ ...agent, languages: e.target.value })} /></Field>
          <Field label="Hand-over contact" hint="Given to customers when a person is needed."><input className={inputClass} maxLength={200} value={agent.handoff_contact} onChange={(e) => setAgent({ ...agent, handoff_contact: e.target.value })} /></Field>
        </div>
        <Field label="Greeting"><input className={inputClass} maxLength={300} value={agent.greeting} onChange={(e) => setAgent({ ...agent, greeting: e.target.value })} /></Field>
        <Field label="Extra instructions" hint="Anything the assistant should always do or never do."><textarea rows={3} maxLength={2000} className={`${inputClass} py-2`} value={agent.extra_instructions} onChange={(e) => setAgent({ ...agent, extra_instructions: e.target.value })} /></Field>
        <div>
          <p className="mb-2 font-semibold">Questions customers often ask</p>
          <div className="space-y-3">
            {faqs.map((f, i) => (
              <div key={i} className="space-y-2 rounded-xl bg-paper p-3">
                <input aria-label="Question" placeholder="Question" className={inputClass} maxLength={300} value={f.question} onChange={(e) => setFaqs(faqs.map((x, j) => (j === i ? { ...x, question: e.target.value } : x)))} />
                <textarea aria-label="Answer" placeholder="Answer" rows={2} className={`${inputClass} py-2`} maxLength={2000} value={f.answer} onChange={(e) => setFaqs(faqs.map((x, j) => (j === i ? { ...x, answer: e.target.value } : x)))} />
                <button type="button" className="font-semibold text-rose" onClick={() => setFaqs(faqs.filter((_, j) => j !== i))}>Remove</button>
              </div>
            ))}
          </div>
          <Button variant="quiet" className="mt-3" onClick={() => setFaqs([...faqs, { question: "", answer: "" }])}>Add a question</Button>
        </div>
      </Section>

      <Section title="Customer emails" hint={p.email.delivers ? `Emails are sent through ${p.email.name.toUpperCase()}.` : "No email provider is set up, so nothing is sent yet. Bookings and tickets still work; each message is recorded as not sent. See the README to connect SMTP."}
        onSave={() => save({ policies: { email_notifications: pol.email_notifications, reminder_hours_before: pol.reminder_hours_before } })}>
        <label className="flex items-center gap-2.5">
          <input type="checkbox" className="size-5 accent-[var(--color-brand)]" checked={Boolean(pol.email_notifications)} onChange={(e) => setPol({ ...pol, email_notifications: e.target.checked })} />
          Email customers their confirmation, changes and cancellation
        </label>
        <div className="max-w-xs">{polNum("reminder_hours_before", "Reminder (hours before)", "0 turns reminders off.", 168)}</div>
      </Section>

      <Section title="Phone number: texts and calls"
        hint={p.phone.connected ? `Connected to ${p.phone.number}. Customers can ${[p.phone.sms && "text", p.phone.voice && "call"].filter(Boolean).join(" or ") || "not reach the assistant on"} this number and the assistant answers.` : "Give the assistant a regular phone number. Customers text it or call it, and it books with the same rules as your booking page."}
        saveLabel={p.phone.connected ? "Update number" : "Connect number"}
        onSave={p.phone.platformReady ? () => api(`/api/b/${p.businessId}/integrations/phone`, { method: "PUT", body: ph }) : undefined}>
        {!p.phone.platformReady && <Notice tone="warn">Phone is not switched on for this installation yet. The server needs TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN from a Twilio account. See docs/PHONE.md.</Notice>}
        {p.phone.platformReady && !p.phone.publicUrl && <Notice tone="warn">The phone provider can only reach a public https address. This server is running at a local address, so texts and calls will not arrive until it is deployed.</Notice>}
        {p.phone.lastError && <Notice tone="error">{p.phone.lastError} In the US this usually means the number is not yet registered for business texting.</Notice>}
        {p.phone.platformReady && (
          <>
            <div className="grid gap-4 sm:grid-cols-2">
              <Field label="Assistant's phone number" hint="The number you bought from the provider, in international format."><input className={inputClass} type="tel" placeholder="+14155550100" value={ph.number} onChange={(e) => setPh({ ...ph, number: e.target.value })} /></Field>
              <Field label="Staff number for hand-over (optional)" hint="Callers are connected here when they ask for a person. It must be a different number."><input className={inputClass} type="tel" placeholder="+14155550199" value={ph.transferTo} onChange={(e) => setPh({ ...ph, transferTo: e.target.value })} /></Field>
            </div>
            <label className="flex items-center gap-2.5"><input type="checkbox" className="size-5 accent-[var(--color-brand)]" checked={ph.sms} onChange={(e) => setPh({ ...ph, sms: e.target.checked })} />Answer text messages</label>
            <label className="flex items-center gap-2.5"><input type="checkbox" className="size-5 accent-[var(--color-brand)]" checked={ph.voice} onChange={(e) => setPh({ ...ph, voice: e.target.checked })} />Answer phone calls</label>
            <p className="text-[15px] text-ink-soft">Addresses to enter for this number at the provider. Messaging: <span className="font-semibold break-all">{p.phone.smsUrl}</span>. Voice: <span className="font-semibold break-all">{p.phone.voiceUrl}</span></p>
            {p.phone.connected && <button type="button" className="font-semibold text-rose" onClick={async () => { await api(`/api/b/${p.businessId}/integrations/phone`, { method: "DELETE" }); router.refresh(); }}>Disconnect this number</button>}
          </>
        )}
      </Section>

      <Section title="WhatsApp"
        hint={p.whatsapp.connected ? `Connected${p.whatsapp.displayNumber ? ` to ${p.whatsapp.displayNumber}` : ""}. Customers who message this number are answered by the assistant.` : "Let customers book by messaging your WhatsApp Business number. The assistant answers there with the same rules as on your booking page."}
        saveLabel={p.whatsapp.connected ? "Update connection" : "Connect WhatsApp"}
        onSave={p.whatsapp.platformReady ? async () => { await api(`/api/b/${p.businessId}/integrations/whatsapp`, { method: "PUT", body: wa }); setWa({ ...wa, accessToken: "" }); } : undefined}>
        {!p.whatsapp.platformReady && <Notice tone="warn">WhatsApp is not switched on for this installation yet. The server needs WHATSAPP_APP_SECRET and WHATSAPP_VERIFY_TOKEN from a Meta developer app. See docs/WHATSAPP.md.</Notice>}
        {p.whatsapp.platformReady && !p.whatsapp.publicUrl && <Notice tone="warn">Meta can only deliver messages to a public https address. This server is running at a local address, so WhatsApp will not reach it until it is deployed.</Notice>}
        {p.whatsapp.status === "needs_attention" && <Notice tone="error">Replies are failing: {p.whatsapp.lastError} The access token has probably expired. Paste a new one below.</Notice>}
        {p.whatsapp.platformReady && (
          <>
            <div className="grid gap-4 sm:grid-cols-2">
              <Field label="Phone number ID" hint="From Meta: WhatsApp, API Setup. Digits only; not the phone number itself."><input className={inputClass} inputMode="numeric" value={wa.phoneNumberId} onChange={(e) => setWa({ ...wa, phoneNumberId: e.target.value })} /></Field>
              <Field label="WhatsApp number (for display)"><input className={inputClass} placeholder="+1 555 010 0000" value={wa.displayNumber} onChange={(e) => setWa({ ...wa, displayNumber: e.target.value })} /></Field>
            </div>
            <Field label="Access token" hint={p.whatsapp.connected ? "Stored encrypted and never shown again. Paste a token only to replace it." : "A permanent System User token is best; temporary tokens stop working after about a day."}>
              <input type="password" autoComplete="off" className={inputClass} value={wa.accessToken} onChange={(e) => setWa({ ...wa, accessToken: e.target.value })} />
            </Field>
            <p className="text-[15px] text-ink-soft">Webhook address to enter in Meta: <span className="font-semibold break-all">{p.whatsapp.webhookUrl}</span></p>
            {p.whatsapp.connected && <button type="button" className="font-semibold text-rose" onClick={async () => { await api(`/api/b/${p.businessId}/integrations/whatsapp`, { method: "DELETE" }); router.refresh(); }}>Disconnect WhatsApp</button>}
          </>
        )}
      </Section>

      {p.team && (
        <Section title="Team" hint="Staff can view, add and check in reservations. Managers can also change, cancel and edit settings.">
          <ul className="divide-y divide-line rounded-xl ring-1 ring-line">
            {p.team.members.map((m) => (
              <li key={m.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                <span className="min-w-0"><strong>{m.name}</strong> <span className="text-ink-soft">{m.email}</span></span>
                <span className="flex items-center gap-3"><span className="capitalize text-ink-soft">{m.role}</span>
                  {m.role !== "owner" && <button type="button" className="font-semibold text-rose" onClick={async () => { await api(`/api/b/${p.businessId}/team?user=${m.id}`, { method: "DELETE" }); router.refresh(); }}>Remove</button>}
                </span>
              </li>
            ))}
            {p.team.invitations.map((v) => (
              <li key={v.id} className="flex items-center justify-between gap-3 px-4 py-2.5 text-ink-soft">
                <span>{v.email} <span className="text-muted">(invited as {v.role})</span></span>
                <button type="button" className="font-semibold text-rose" onClick={async () => { await api(`/api/b/${p.businessId}/team?invitation=${v.id}`, { method: "DELETE" }); router.refresh(); }}>Withdraw</button>
              </li>
            ))}
          </ul>
          <div className="grid items-end gap-3 sm:grid-cols-[1.6fr_1fr_auto]">
            <Field label="Email to invite"><input type="email" className={inputClass} value={invite.email} onChange={(e) => setInvite({ ...invite, email: e.target.value })} /></Field>
            <Field label="Role"><select className={inputClass} value={invite.role} onChange={(e) => setInvite({ ...invite, role: e.target.value })}><option value="staff">Staff</option><option value="manager">Manager</option></select></Field>
            <Button variant="quiet" disabled={!invite.email} onClick={async () => {
              try { const r = await api<{ inviteUrl: string }>(`/api/b/${p.businessId}/team`, { body: { email: invite.email, role: invite.role } }); setInvite({ email: "", role: "staff", url: r.inviteUrl, error: "" }); router.refresh(); }
              catch (e) { setInvite({ ...invite, error: (e as Error).message, url: "" }); }
            }}>Create invitation</Button>
          </div>
          {invite.error && <Notice tone="error">{invite.error}</Notice>}
          {invite.url && <Notice tone="ok">Send this link to your colleague (valid for 7 days). It is not emailed automatically.<br /><span className="font-semibold break-all" data-testid="invite-url">{invite.url}</span></Notice>}
        </Section>
      )}
    </div>
  );
}
